steps.message:
THOUGHT: I’ll add shared HTTP helpers, authentication, cursor validation, resource serialization, and atomic event emission. Keeping these concerns centralized lets the route handlers remain small while ensuring identical behavior across all three processes.

```mswea_bash_command
cat > /app/common.py <<'PY'
import json,base64,re,sqlite3
from aiohttp import web
from db import connect,now_iso
class HTTPError(Exception):
 def __init__(self,status,msg): self.status=status; self.msg=msg
@web.middleware
async def error_middleware(request,handler):
 try: return await handler(request)
 except HTTPError as e: return web.json_response({'error':e.msg},status=e.status)
 except web.HTTPException: raise
 except Exception as e: return web.json_response({'error':str(e)},status=500)
async def read_json(r):
 try: return await r.json()
 except: raise HTTPError(400,'invalid json')
def require_user(r):
 t=r.headers.get('Authorization','')
 if not t.startswith('Bearer '): raise HTTPError(401,'authentication required')
 c=connect(); x=c.execute('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(t[7:],)).fetchone(); c.close()
 if not x: raise HTTPError(401,'invalid token')
 return x
def user_to_json(x):
 return {k:x[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
def parse_limit(r):
 try: n=int(r.query.get('limit','50'))
 except: raise HTTPError(400,'invalid limit')
 if n<1 or n>200: raise HTTPError(400,'invalid limit')
 return n
def encode_cursor(n): return base64.urlsafe_b64encode(json.dumps({'k':n}).encode()).decode()
def decode_cursor(s):
 if not s:return None
 try:
  x=json.loads(base64.urlsafe_b64decode(s.encode())); n=x['k']
  if not isinstance(n,int): raise ValueError()
  return n
 except: raise HTTPError(400,'invalid cursor')
def emit_event(cid,kind,data):
 c=connect()
 try:
  c.execute('BEGIN IMMEDIATE'); c.execute('UPDATE channels SET last_event_id=last_event_id+1 WHERE id=?',(cid,))
  eid=c.execute('SELECT last_event_id FROM channels WHERE id=?',(cid,)).fetchone()[0]
  p={'type':kind,'event_id':eid,'channel_id':cid};p.update(data)
  c.execute('INSERT INTO events(channel_id,event_id,payload) VALUES(?,?,?)',(cid,eid,json.dumps(p)));c.execute('COMMIT');return eid
 except: c.execute('ROLLBACK');raise
 finally:c.close()
def broadcast_global(p):
 c=connect();c.execute('INSERT INTO broadcasts(payload) VALUES(?)',(json.dumps(p),));c.close()
PY
cat > /app/routes_auth.py <<'PY'
import secrets,re,hashlib
from aiohttp import web
from db import connect,now_iso
from common import *
def setup(app):
 async def register(r):
  d=await read_json(r); u=d.get('username','');pw=d.get('password','')
  if not re.fullmatch(r'[A-Za-z0-9_]{1,32}',u) or len(pw)<8: raise HTTPError(400,'invalid registration')
  c=connect()
  try:
   c.execute('INSERT INTO users(username,password,display_name,created_at) VALUES(?,?,?,?)',(u,hashlib.sha256(pw.encode()).hexdigest(),d.get('display_name') or u,now_iso()))
  except: c.close();raise HTTPError(409,'username exists')
  uid=c.execute('SELECT last_insert_rowid()').fetchone()[0];t=secrets.token_urlsafe(24);c.execute('INSERT INTO tokens VALUES(?,?)',(t,uid));x=c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone();c.close()
  return web.json_response({'user':user_to_json(x),'token':t},status=201)
 async def login(r):
  d=await read_json(r);c=connect();x=c.execute('SELECT * FROM users WHERE username=? AND password=?',(d.get('username'),hashlib.sha256(d.get('password','').encode()).hexdigest())).fetchone()
  if not x:c.close();raise HTTPError(401,'wrong credentials')
  t=secrets.token_urlsafe(24);c.execute('INSERT INTO tokens VALUES(?,?)',(t,x['id']));c.close();return web.json_response({'user':user_to_json(x),'token':t})
 async def me(r): return web.json_response({'user':user_to_json(require_user(r))})
 app.router.add_post('/api/auth/register',register);app.router.add_post('/api/auth/login',login);app.router.add_get('/api/auth/me',me)
PY
```

