```mswea_bash_command
cat > /app/static/app.js <<'JS'
(() => {
  const q = new URLSearchParams(location.search);
  const token = q.get('token') || localStorage.getItem('huddle.token');
  if (q.get('token')) localStorage.setItem('huddle.token', token);
  const auth = document.getElementById('auth-modal');
  if (token) auth.hidden = true;
  const form = document.querySelector('[data-testid="auth-form"]');
  const error = form && form.querySelector('.error');
  if (form) form.addEventListener('submit', async e => {
    e.preventDefault();
    const fd = new FormData(form), mode = form.dataset.mode || 'login';
    const body = {username: fd.get('username'), password: fd.get('password')};
    if (mode === 'register') body.display_name = fd.get('display_name') || undefined;
    try {
      const r = await fetch('/api/auth/' + (mode === 'register' ? 'register' : 'login'), {
        method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)
      });
      const data = await r.json();
      if (!r.ok) throw Error(data.error || 'Request failed');
      localStorage.setItem('huddle.token', data.token);
      auth.hidden = true;
    } catch (x) { if (error) error.textContent = x.message; }
  });
  const toggle = document.querySelector('[data-testid="auth-toggle"]');
  if (toggle) toggle.addEventListener('click', () => {
    const signup = form.dataset.mode !== 'register';
    form.dataset.mode = signup ? 'register' : 'login';
    document.querySelector('.auth-title').textContent = signup ? 'Sign up for Huddle' : 'Log in to Huddle';
    document.querySelector('[data-testid="auth-submit"]').textContent = signup ? 'Sign up' : 'Log in';
  });
})();
